ck();await expect(drawer.getByRole('tab',{name:/Terminal New/})).toHaveCount(0);await expect(drawer.getByRole('tab',{name:/Tests/})).toHaveAttribute('aria-selected','true');await drawer.getByRole('tab',{name:/Tests/}).click({button:'right',modifiers:['Alt']});await expect(terminalMenu.getByText('Close Tabs to the Left')).toBeVisible();await page.screenshot({path:'/private/tmp/hs2-9n837w-terminal-tabs-wide.png',fullPage:true});await page.keyboard.press('Escape');
