test('holds terminal geometry throughout a slow drawer drag and fits once it settles',async({page})=>{
  await page.setViewportSize({width:1440,height:900});await installFakeTerminalSockets(page,true);await mockProject(page);await page.goto('/');await page.getByRole('button',{name:'Open project'}).click();await page.getByRole('button',{name:'Open project',exact:true}).last().click();await page.getByRole('button',{name:'Show terminal drawer'}).click();const drawer=page.locator('[data-component="terminal-drawer"]');await drawer.getByRole('tab',{name:/Codex Main/}).click();const viewport=drawer.locator('[data-component="terminal-session"] [data-component="terminal-viewport"]');await expect(viewport).toHaveAttribute('data-connection','connected');await viewport.click();const claimCount=()=>page.evaluate(() => {const sockets=(window as unknown as {__terminalSockets:Array<{url:string;sent:unknown[]}>}).__terminalSockets,socket=sockets.filter(item=>item.url.includes('codex-main')).at(-1);return socket?.sent.filter(value=>typeof value==='string'&&value.startsWith('{')).length??0});await expect.poll(claimCount).toBeGreaterThan(0);const initialClaims=await claimCount(),initialGrid=await viewport.getAttribute('data-grid-size'),initialScreen=await viewport.locator('.xterm-screen').boundingBox(),handle=page.getByRole('separator',{name:'Resize Terminal drawer'}),grip=(await handle.boundingBox())!;await page.mouse.move(grip.x+grip.width/2,grip.y+grip.height/2);await page.mouse.down();await page.mouse.move(grip.x+grip.width/2,grip.y-80,{steps:8});await page.waitForTimeout(220);expect(await claimCount()).toBe(initialClaims);await expect(viewport).toHaveAttribute('data-grid-size',initialGrid!);expect(await viewport.locator('.xterm-screen').evaluate(element=>({width:element.getBoundingClientRect().width,height:element.getBoundingClientRect().height}))).toEqual({width:initialScreen!.width,height:initialScreen!.height});await page.mouse.move(grip.x+grip.width/2,grip.y-180,{steps:10});await page.waitForTimeout(220);expect(await claimCount()).toBe(initialClaims);await expect(viewport).toHaveAttribute('data-grid-size',initialGrid!);await page.screenshot({path:'/private/tmp/hs2-rjev3s-slow-drawer-drag.png',fullPage:true});await page.mouse.up();await expect.poll(claimCount,{timeout:800}).toBeGreaterThan(initialClaims);await expect(viewport).toHaveAttribute('data-driving','true');
  await drawer.getByRole('tab',{name:'Terminal grid'}).click();const dashboard=drawer.getByRole('region',{name:'Terminal dashboard'});await dashboard.getByRole('button',{name:/Zoom in/}).click();await expect(dashboard).toHaveAttribute('data-fit','1');const tile=dashboard.locator('.terminal-tile').first(),initialTileHeight=await tile.evaluate(element=>element.getBoundingClientRect().height),gridGrip=(await handle.boundingBox())!;await page.mouse.move(gridGrip.x+gridGrip.width/2,gridGrip.y+gridGrip.height/2);await page.mouse.down();await page.mouse.move(gridGrip.x+gridGrip.width/2,gridGrip.y+80,{steps:8});await page.waitForTimeout(220);expect(await tile.evaluate(element=>element.getBoundingClientRect().height)).toBe(initialTileHeight);await page.mouse.up();await expect.poll(()=>tile.evaluate(element=>element.getBoundingClientRect().height)).not.toBe(initialTileHeight);
});

